window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[106]={"id":"106","numero":106,"titre":"Item 106 — Maladie de Parkinson","objectifs":[{"id":"106-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","contenu":"<p>La <span class=\"kw-def\">maladie de Parkinson</span> peut être inaugurée par des <span class=\"kw-clinique\">prodromes non moteurs</span> précédant les signes cardinaux de <span class=\"kw-chiffre\">plusieurs années</span>, ou par des <span class=\"kw-clinique\">signes révélateurs trompeurs</span> mimant une autre pathologie en l'absence de tremblement de repos.</p>\n\n<table >\n  <thead>\n    <tr><th>Mode de révélation</th><th>Manifestations</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Prodromes non moteurs</strong> <em>(plusieurs années avant les signes moteurs)</em></td>\n      <td>\n        <strong>Digestif :</strong> <span class=\"kw-clinique\">constipation</span> ;<br>\n        <strong>Olfaction :</strong> <span class=\"kw-clinique\">hyposmie</span> / <span class=\"kw-clinique\">déficit de l'odorat</span> (atteinte du <span class=\"kw-def\">noyau du nerf olfactif</span>) ;<br>\n        <strong>Sommeil :</strong> <span class=\"kw-def\">troubles du comportement en sommeil paradoxal</span> (RBD) — <span class=\"kw-clinique\">rêves animés</span>, <span class=\"kw-clinique\">cauchemars</span>, <span class=\"kw-alerte\">actes auto- et hétéro-agressifs</span> ;<br>\n        <strong>Douleur :</strong> <span class=\"kw-clinique\">douleur mécanique de l'épaule</span>.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Signes révélateurs trompeurs</strong> <em>(syndrome akinéto-rigide sans <span class=\"kw-clinique\">tremblement</span>)</em></td>\n      <td>\n        <strong>Rhumatologique :</strong> <span class=\"kw-clinique\">raideur d'un membre</span>, <span class=\"kw-def\">périarthrite scapulo-humérale</span> (fréquente dans Parkinson) ;<br>\n        <strong>Neuropsychique :</strong> <span class=\"kw-clinique\">ralentissement psychomoteur</span> évoquant une <span class=\"kw-clinique\">dépression</span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 107 — Mouvements anormaux</em></p>","frequence":3},{"id":"106-2","rang":"A","rubrique":"Diagnostic positif","titre":"Décrire les signes cliniques d’une maladie de Parkinson","contenu":"<p>Le <span class=\"kw-def\">syndrome parkinsonien</span> = <strong>bradykinésie + [rigidité plastique et/ou tremblement de repos]</strong>. Une caractéristique cardinale : <strong>début <span class=\"kw-clinique\">unilatéral</span> ou <span class=\"kw-clinique\">asymétrique</span></strong>, l'<span class=\"kw-clinique\">asymétrie</span> persistant tout au long de la maladie.</p>\n\n<table >\n  <thead>\n    <tr><th>Signe cardinal</th><th>Définition</th><th>Manifestations cliniques</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Bradykinésie</strong></td>\n      <td>Mouvements plus <span class=\"kw-clinique\">lents</span> (ralentissement à l'exécution, décrément de la vitesse). Associée parfois à : <strong>Hypokinésie</strong> (mouvements moins amples), <strong>Akinésie</strong> (défaut d'initiation).</td>\n      <td>\n        <strong>Écriture :</strong> <span class=\"kw-clinique\">micrographie</span> (<span class=\"kw-ttt\">réduction</span> de la taille des lettres) ;<br>\n        <strong>Phonation :</strong> <span class=\"kw-clinique\">voix monocorde et monotone</span> ;<br>\n        <strong>Marche :</strong> <span class=\"kw-clinique\">lenteur, marche à petits pas, perte du ballant du bras</span> ;<br>\n        <strong>Face :</strong> <span class=\"kw-clinique\">hypomimie</span>, pauvreté des mouvements spontanés (clignement des yeux) ;<br>\n        <strong>Membres :</strong> ralentissement des gestes alternatifs rapides — <span class=\"kw-clinique\">opposition pouce-index</span>, <span class=\"kw-clinique\">battre à mesure avec le pied</span> <em>(et non doigt-nez, qui explore le <span class=\"kw-def\">syndrome cérébelleux</span>)</em>.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Rigidité plastique « en tuyau de plomb »</strong></td>\n      <td>Rigidité <span class=\"kw-def\">plastique</span> (ne revient pas à sa forme initiale), à différencier de la rigidité spastique.</td>\n      <td>\n        <strong>Topographie :</strong> <span class=\"kw-clinique\">extrémités</span> et <span class=\"kw-clinique\">nuque</span> ;<br>\n        <strong>Mobilisation passive :</strong> résistance constante qui cède par à-coups en <span class=\"kw-def\">« roue dentée »</span> ;<br>\n        <strong>Sensibilisation :</strong> <span class=\"kw-clinique\">manœuvre de Froment</span> — mouvements passifs d'une main + tâche volontaire avec l'autre main = rigidité majorée du côté passif.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Tremblement de repos</strong></td>\n      <td>Tremblement <span class=\"kw-clinique\">lent</span>, <span class=\"kw-clinique\">asymétrique</span>, disparaissant au mouvement et au sommeil.</td>\n      <td>\n        <strong>Fréquence :</strong> <span class=\"kw-chiffre\">4-6 Hz</span> ;<br>\n        <strong>Latéralité :</strong> <span class=\"kw-clinique\">unilatéral</span> ou <span class=\"kw-clinique\">asymétrique</span> ;<br>\n        <strong>Topographie :</strong> membres en distalité, lèvres, menton, langue — <strong>ne touche pas le chef (la tête)</strong> ;<br>\n        <strong>Facteurs aggravants :</strong> <span class=\"kw-clinique\">émotion</span>, <span class=\"kw-clinique\">calcul mental</span> ;<br>\n        <strong>Facteurs calmants :</strong> disparaît lors du <span class=\"kw-clinique\">mouvement volontaire</span> et du <span class=\"kw-clinique\">sommeil</span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 107 — Mouvements anormaux · 91 — Déficit neuro récent</em></p>","frequence":6},{"id":"106-3","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître le processus physiopathologique de la maladie de Parkinson","contenu":"<h4>Substrat anatomique</h4>\n<p>Les <span class=\"kw-def\">ganglions de la base</span> sous-tendent la voie motrice extrapyramidale :</p>\n<ul>\n  <li><span class=\"kw-def\">Striatum</span> = noyau caudé + putamen ;</li>\n  <li>Noyau lenticulaire = striatum + pallidum.</li>\n</ul>\n\n<h4>Mécanisme dégénératif</h4>\n<p>Processus <span class=\"kw-def\">dégénératif</span> avec perte progressive des <span class=\"kw-def\">neurones dopaminergiques</span> de la <span class=\"kw-def\">voie nigro-striatale</span>, marqué par la présence de <span class=\"kw-def\">corps de Lewy</span> = inclusions intraneuronales contenant des agrégats anormaux d'<span class=\"kw-def\">alpha-synucléine</span>.</p>\n<ol>\n  <li>Les signes moteurs apparaissent après une <span class=\"kw-chiffre\">perte de 50 à 60 %</span> des neurones dopaminergiques.</li>\n  <li>Lorsque le processus dégénératif <strong>dépasse la voie nigro-striatale</strong>, apparaissent :\n    <ul>\n      <li>Signes moteurs <span class=\"kw-clinique\">résistants au traitement</span> (signes axiaux) ;</li>\n      <li>Signes non moteurs résistants au traitement (troubles cognitifs).</li>\n    </ul>\n  </li>\n</ol>\n\n<figure class=\"obj-figure\">\n  <svg class=\"atlas-fig\" viewBox=\"0 0 620 470\" role=\"img\" aria-label=\"Schéma du processus physiopathologique de la maladie de Parkinson. Sous l'influence de facteurs de risque (âge, exposition aux pesticides, mutations génétiques), un processus dégénératif détruit progressivement les neurones dopaminergiques de la voie nigro-striatale, marqué par des corps de Lewy contenant des agrégats d'alpha-synucléine. Les signes moteurs parkinsoniens n'apparaissent qu'après la perte de 50 à 60 pour cent des neurones dopaminergiques. Lorsque le processus dégénératif dépasse la voie nigro-striatale, surviennent des signes axiaux et des troubles cognitifs résistants au traitement dopaminergique.\" style=\"height:auto;display:block;border-radius:8px\">\n    <rect class=\"fb-grey\" x=\"120\" y=\"12\" width=\"320\" height=\"44\" rx=\"6\"/>\n    <text class=\"tx-grey\" x=\"280\" y=\"31\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span class=\"kw-def\">Facteurs de risque</span></text>\n    <text class=\"tx-grey\" x=\"280\" y=\"48\" text-anchor=\"middle\" font-size=\"11\">âge · pesticides · mutations génétiques</text>\n    <line class=\"ln\" x1=\"280\" y1=\"56\" x2=\"280\" y2=\"74\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"280,80 275,72 285,72\"/>\n    <rect class=\"fb-red\" x=\"98\" y=\"82\" width=\"364\" height=\"48\" rx=\"6\"/>\n    <text class=\"tx-red\" x=\"280\" y=\"101\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">Dégénérescence nigro-striatale</text>\n    <text class=\"tx-red\" x=\"280\" y=\"119\" text-anchor=\"middle\" font-size=\"11.5\">perte progressive des neurones dopaminergiques</text>\n    <rect class=\"fb-amber\" x=\"450\" y=\"138\" width=\"160\" height=\"52\" rx=\"6\"/>\n    <text class=\"tx-amber\" x=\"530\" y=\"156\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Corps de Lewy</text>\n    <text class=\"tx-amber\" x=\"530\" y=\"171\" text-anchor=\"middle\" font-size=\"10\">agrégats anormaux</text>\n    <text class=\"tx-amber\" x=\"530\" y=\"184\" text-anchor=\"middle\" font-size=\"10\">d'alpha-synucléine</text>\n    <line class=\"ln\" x1=\"450\" y1=\"138\" x2=\"450\" y2=\"130\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"450,124 445,132 455,132\"/>\n    <line class=\"ln\" x1=\"280\" y1=\"130\" x2=\"280\" y2=\"148\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"280,154 275,146 285,146\"/>\n    <rect class=\"fb-red\" x=\"118\" y=\"156\" width=\"324\" height=\"42\" rx=\"6\"/>\n    <text class=\"tx-red\" x=\"280\" y=\"173\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Seuil : perte de <span class=\"kw-chiffre\">50 à 60 %</span> des neurones</text>\n    <text class=\"tx-red\" x=\"280\" y=\"190\" text-anchor=\"middle\" font-size=\"11\">→ apparition des signes moteurs</text>\n    <line class=\"ln\" x1=\"280\" y1=\"198\" x2=\"280\" y2=\"216\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"280,222 275,214 285,214\"/>\n    <rect class=\"fb-amber\" x=\"112\" y=\"224\" width=\"336\" height=\"46\" rx=\"6\"/>\n    <text class=\"tx-amber\" x=\"280\" y=\"243\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Signes moteurs parkinsoniens</text>\n    <text class=\"tx-amber\" x=\"280\" y=\"261\" text-anchor=\"middle\" font-size=\"11\">dopasensibles (bradykinésie, rigidité, tremblement)</text>\n    <line class=\"ln\" x1=\"280\" y1=\"270\" x2=\"280\" y2=\"288\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"280,294 275,286 285,286\"/>\n    <rect class=\"fb-grey\" x=\"60\" y=\"296\" width=\"440\" height=\"40\" rx=\"6\"/>\n    <text class=\"tx-grey\" x=\"280\" y=\"320\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Le processus dégénératif dépasse la voie nigro-striatale</text>\n    <line class=\"ln\" x1=\"280\" y1=\"336\" x2=\"280\" y2=\"352\" stroke-width=\"2\"/>\n    <line class=\"ln\" x1=\"160\" y1=\"352\" x2=\"400\" y2=\"352\" stroke-width=\"2\"/>\n    <line class=\"ln\" x1=\"160\" y1=\"352\" x2=\"160\" y2=\"370\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"160,376 155,368 165,368\"/>\n    <line class=\"ln\" x1=\"400\" y1=\"352\" x2=\"400\" y2=\"370\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"400,376 395,368 405,368\"/>\n    <rect class=\"fb-red\" x=\"30\" y=\"378\" width=\"260\" height=\"52\" rx=\"6\"/>\n    <text class=\"tx-red\" x=\"160\" y=\"397\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Signes moteurs axiaux</text>\n    <text class=\"tx-red\" x=\"160\" y=\"414\" text-anchor=\"middle\" font-size=\"10.5\">résistants au traitement dopaminergique</text>\n    <rect class=\"fb-red\" x=\"270\" y=\"378\" width=\"260\" height=\"52\" rx=\"6\"/>\n    <text class=\"tx-red\" x=\"400\" y=\"397\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Troubles cognitifs</text>\n    <text class=\"tx-red\" x=\"400\" y=\"414\" text-anchor=\"middle\" font-size=\"10.5\">non moteurs, résistants au traitement</text>\n    <text class=\"tx-muted\" x=\"280\" y=\"452\" text-anchor=\"middle\" font-size=\"10.5\" font-style=\"italic\">Étiologie inconnue · <span class=\"kw-def\">prévalence</span> 2,5 / 1000 · âge moyen <span class=\"kw-chiffre\">60 ans</span></text>\n  </svg>\n  <figcaption>Cascade dégénérative : la perte dopaminergique nigro-striatale (corps de Lewy à l'alpha-synucléine) reste muette jusqu'au seuil de <span class=\"kw-chiffre\">50-60 %</span> ; au-delà de la voie nigro-striatale apparaissent les signes axiaux et cognitifs dopa-résistants.</figcaption>\n</figure>\n\n<h4>Étiologies</h4>\n<p>Étiologie inconnue, mais 4 facteurs identifiés :</p>\n<table >\n  <thead><tr><th>Facteur</th><th>Précisions</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Âge</strong></td><td><span class=\"kw-def\">Facteur de risque</span> principal ; <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">2,5 / 1 000</span> augmentant avec l'âge ; âge moyen <span class=\"kw-chiffre\">60 ans</span> ; forme jeune (&lt;<span class=\"kw-chiffre\"> 40 ans</span>) dans <span class=\"kw-chiffre\">10 %</span> des cas.</td></tr>\n    <tr><td><strong>Environnement</strong></td><td><span class=\"kw-clinique\">Exposition aux pesticides</span> (justifie une demande de reconnaissance professionnelle — cf. obj-8).</td></tr>\n    <tr><td><strong><span class=\"kw-etio\">Génétique</span></strong></td><td>Mutations à transmission <span class=\"kw-def\">autosomique récessive</span> ou <span class=\"kw-def\">autosomique dominante</span> : <span class=\"kw-chiffre\">≈ 15 %</span> des patients, <span class=\"kw-chiffre\">50 %</span> de ceux dont la maladie débute avant <span class=\"kw-chiffre\">40 ans</span>.</td></tr>\n    <tr><td><strong>Sex-ratio</strong></td><td>Prédominance masculine (<span class=\"kw-chiffre\">1,5 H / F</span>).</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Morbidité</span></strong></td><td><span class=\"kw-chiffre\">2<sup>e</sup> cause de handicap moteur</span> chez le sujet âgé (après l'<span class=\"kw-def\">AVC</span>).</td></tr>\n  </tbody>\n</table>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/basal-ganglia","label":"Radiopaedia : Basal ganglia (anatomie)"}]},{"id":"106-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","contenu":"<p>Le <span class=\"kw-def\">diagnostic de maladie de Parkinson</span> exige un examen neurologique <strong>normal en dehors du syndrome parkinsonien</strong>. Toute association à l'un des signes ci-dessous est un <span class=\"kw-alerte\">drapeau rouge 🚩</span> orientant vers un <span class=\"kw-def\">syndrome parkinsonien dégénératif atypique</span> ou un autre diagnostic.</p>\n\n<table >\n  <thead>\n    <tr><th><span class=\"kw-alerte\">Drapeau rouge</span> 🚩</th><th>Diagnostic alternatif à évoquer</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Absence de réponse prolongée au traitement dopaminergique</td><td>Syndrome parkinsonien dégénératif atypique, <span class=\"kw-etio\">iatrogène</span> ou vasculaire.</td></tr>\n    <tr><td><span class=\"kw-clinique\">Syndrome cérébelleux</span></td><td><span class=\"kw-etio\">Atrophie multisystématisée</span> (AMS-C : forme à prédominance cérébelleuse).</td></tr>\n    <tr><td>Atteinte pyramidale</td><td>AMS, syndrome parkinsonien vasculaire.</td></tr>\n    <tr><td>Troubles oculomoteurs</td><td><span class=\"kw-etio\">Paralysie supra-nucléaire progressive</span> (maladie de Steele-Richardson).</td></tr>\n    <tr><td>Signes corticaux : <span class=\"kw-clinique\">aphasie</span>, apraxie, myoclonies, astéréognosie</td><td><span class=\"kw-etio\">Dégénérescence cortico-basale</span>.</td></tr>\n    <tr><td>Progression rapide avec chutes précoces</td><td>PSP, AMS, démence à corps de Lewy.</td></tr>\n    <tr><td>Atteinte cognitive précoce</td><td><span class=\"kw-etio\">Démence à corps de Lewy</span> (atteinte cognitive contemporaine ou précédant le syndrome parkinsonien).</td></tr>\n    <tr><td>Signes pseudo-bulbaires précoces : <span class=\"kw-clinique\">dysarthrie</span>, dysphagie</td><td>PSP, AMS.</td></tr>\n    <tr><td>Dysautonomie précoce : HTO sévère, incontinence urinaire</td><td><span class=\"kw-def\">AMS</span> (incontinence urinaire + HTO sévère = signature).</td></tr>\n  </tbody>\n</table>\n\n<h4>Paraclinique en cas de doute</h4>\n<p>Le diagnostic est <span class=\"kw-def\">clinique</span> : aucun examen paraclinique n'est justifié si la présentation est typique. Indiqué dans <span class=\"kw-chiffre\">2 situations</span> :</p>\n<ul>\n  <li>Patient de <span class=\"kw-chiffre\">moins de 40 ans</span> → éliminer une <span class=\"kw-etio\">maladie de Wilson</span> : <span class=\"kw-imagerie\">IRM cérébrale</span> + <span class=\"kw-bio\">bilan du cuivre</span> ;</li>\n  <li>Doute avec un <span class=\"kw-etio\">tremblement essentiel</span> → <span class=\"kw-imagerie\">scintigraphie cérébrale au DaTSCAN</span> ou <span class=\"kw-imagerie\">PET à la fluorodopa</span>.</li>\n</ul>\n<p class=\"obj-renvois\"><em>📎 Items liés : 104 — SEP · 91 — Déficit neuro récent</em></p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/wilson-disease-2","label":"Radiopaedia : Wilson disease"}]},{"id":"106-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations de la phase des complications motrices","contenu":"<p>La <span class=\"kw-def\">phase des complications motrices</span> du traitement dopaminergique survient <span class=\"kw-chiffre\">4 à 5 ans</span> après le début de la maladie, après une <span class=\"kw-def\">phase de bon contrôle (« lune de miel »)</span>. <strong><span class=\"kw-def\">Facteurs de risque</span> d'apparition précoce :</strong> <span class=\"kw-clinique\">âge jeune au début de la maladie</span>, <span class=\"kw-clinique\">dose de L-DOPA élevée</span>, <span class=\"kw-clinique\">durée d'évolution</span>.</p>\n\n<figure class=\"obj-figure\">\n  <svg class=\"atlas-fig\" viewBox=\"0 0 560 280\" role=\"img\" aria-label=\"Frise de l'histoire naturelle motrice de la maladie de Parkinson sous traitement. Au début, la phase de bon contrôle des signes dite lune de miel. Puis, environ 4 à 5 ans après le début de la maladie, la phase des complications motrices du traitement dopaminergique, faite de fluctuations d'efficacité, comme l'akinésie de fin de dose et le phénomène on-off, et de dyskinésies. Enfin, après 15 à 20 ans d'évolution, la phase de déclin axial et cognitif, avec des signes axiaux et des troubles cognitifs peu ou pas sensibles aux traitements dopaminergiques, la démence touchant jusqu'à 80 pour cent des patients.\" style=\"height:auto;display:block;border-radius:8px\">\n    <line class=\"ln\" x1=\"24\" y1=\"60\" x2=\"512\" y2=\"60\" stroke-width=\"2.5\"/>\n    <polygon class=\"ah\" points=\"536,60 524,54 524,66\"/>\n    <text class=\"tx-muted\" x=\"520\" y=\"48\" text-anchor=\"end\" font-size=\"10.5\" font-style=\"italic\">temps</text>\n    <line class=\"ln\" x1=\"200\" y1=\"54\" x2=\"200\" y2=\"66\" stroke-width=\"2\"/>\n    <text class=\"tx-muted\" x=\"200\" y=\"82\" text-anchor=\"middle\" font-size=\"10.5\">≈<span class=\"kw-chiffre\"> 4-5 ans</span></text>\n    <line class=\"ln\" x1=\"392\" y1=\"54\" x2=\"392\" y2=\"66\" stroke-width=\"2\"/>\n    <text class=\"tx-muted\" x=\"392\" y=\"82\" text-anchor=\"middle\" font-size=\"10.5\">≈<span class=\"kw-chiffre\"> 15-20 ans</span></text>\n    <rect class=\"fb-ok\" x=\"24\" y=\"98\" width=\"160\" height=\"68\" rx=\"6\"/>\n    <text class=\"tx-ok\" x=\"104\" y=\"120\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Lune de miel</text>\n    <text class=\"tx-ok\" x=\"104\" y=\"138\" text-anchor=\"middle\" font-size=\"10.5\">bon contrôle des signes</text>\n    <text class=\"tx-ok\" x=\"104\" y=\"153\" text-anchor=\"middle\" font-size=\"10.5\">sous traitement</text>\n    <line class=\"ln\" x1=\"184\" y1=\"132\" x2=\"198\" y2=\"132\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"204,132 196,127 196,137\"/>\n    <rect class=\"fb-amber\" x=\"206\" y=\"92\" width=\"160\" height=\"80\" rx=\"6\"/>\n    <text class=\"tx-amber\" x=\"286\" y=\"111\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Complications</text>\n    <text class=\"tx-amber\" x=\"286\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">motrices</text>\n    <text class=\"tx-amber\" x=\"286\" y=\"143\" text-anchor=\"middle\" font-size=\"10\">fluctuations (fin de dose,</text>\n    <text class=\"tx-amber\" x=\"286\" y=\"156\" text-anchor=\"middle\" font-size=\"10\">ON/OFF) + dyskinésies</text>\n    <line class=\"ln\" x1=\"366\" y1=\"132\" x2=\"380\" y2=\"132\" stroke-width=\"2\"/>\n    <polygon class=\"ah\" points=\"386,132 378,127 378,137\"/>\n    <rect class=\"fb-red\" x=\"388\" y=\"98\" width=\"148\" height=\"68\" rx=\"6\"/>\n    <text class=\"tx-red\" x=\"462\" y=\"118\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">Déclin axial</text>\n    <text class=\"tx-red\" x=\"462\" y=\"133\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">et cognitif</text>\n    <text class=\"tx-red\" x=\"462\" y=\"150\" text-anchor=\"middle\" font-size=\"9.5\">peu / pas dopasensible</text>\n    <text class=\"tx-muted\" x=\"24\" y=\"200\" font-size=\"11\" font-weight=\"600\">Dopasensible</text>\n    <line class=\"ln\" x1=\"120\" y1=\"196\" x2=\"290\" y2=\"196\" stroke-width=\"6\"/>\n    <text class=\"tx-muted\" x=\"300\" y=\"200\" font-size=\"11\" font-weight=\"600\">→ perte de dopasensibilité</text>\n    <text class=\"tx-muted\" x=\"24\" y=\"226\" text-anchor=\"start\" font-size=\"10.5\" font-style=\"italic\">FR d'apparition précoce des complications : âge jeune au début ·<tspan x=\"24\" dy=\"14\">dose de L-DOPA élevée · durée d'<span class=\"kw-clinique\">évolution</span>.</tspan></text>\n    <text class=\"tx-muted\" x=\"24\" y=\"258\" text-anchor=\"start\" font-size=\"10.5\" font-style=\"italic\">Démence :<span class=\"kw-chiffre\"> 30 %</span> des patients, jusqu'à<span class=\"kw-chiffre\"> 80 %</span> après <span class=\"kw-chiffre\">15-20 ans</span> d'évolution.</text>\n  </svg>\n  <figcaption>Histoire naturelle motrice : « lune de miel » initiale, puis complications motrices du traitement vers <span class=\"kw-chiffre\">4-5 ans</span> (fluctuations + dyskinésies), enfin déclin axial et cognitif dopa-résistant après <span class=\"kw-chiffre\">15-20 ans</span>.</figcaption>\n</figure>\n\n<table >\n  <thead>\n    <tr><th>Complication</th><th>Manifestations</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Fluctuations d'efficacité du traitement</strong></td>\n      <td>\n        <strong>Akinésie de fin de dose :</strong> réapparition des signes parkinsoniens avant la prise suivante (durée d'action L-DOPA tombe à <span class=\"kw-chiffre\">60-90 min</span> aux stades avancés, ≈ demi-vie plasmatique) ;<br>\n        <strong>Akinésie de nuit / petit matin :</strong> lenteur, crampes des mollets et orteils, difficultés à se tourner dans le lit ;<br>\n        <strong>Phénomène <span class=\"kw-def\">ON/OFF</span> :</strong> passage brutal de l'état non-parkinsonien à l'état parkinsonien.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Dyskinésies</strong></td>\n      <td>\n        <strong>Dyskinésies de milieu / pic de dose :</strong> mouvements involontaires plutôt <span class=\"kw-clinique\">choréiques</span> des membres et du tronc ;<br>\n        <strong>Dyskinésies biphasiques :</strong> de début ou de fin de dose, plutôt <span class=\"kw-clinique\">dystoniques</span> des membres inférieurs, souvent douloureuses.\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<h4>Signes dopasensibles <span class=\"kw-bio\">vs</span> non dopasensibles</h4>\n<table >\n  <thead>\n    <tr><th>Dopasensibles</th><th>Non dopasensibles</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><span class=\"kw-clinique\">Tremblement de repos</span></td>\n      <td><span class=\"kw-clinique\">Troubles de l'adaptation posturale</span> (chutes — non liés à une dénervation dopaminergique pure, survenue tardive)</td>\n    </tr>\n    <tr>\n      <td><span class=\"kw-clinique\">Bradykinésie</span></td>\n      <td><span class=\"kw-clinique\">Dysarthrie</span></td>\n    </tr>\n    <tr>\n      <td><span class=\"kw-clinique\">Hypertonie plastique</span></td>\n      <td><span class=\"kw-clinique\">Troubles cognitifs</span></td>\n    </tr>\n  </tbody>\n</table>","frequence":1},{"id":"106-6","rang":"B","rubrique":"Diagnostic positif","titre":"Enoncer les manifestations de la phase de déclin moteur","contenu":"<p>La <span class=\"kw-def\">phase de déclin moteur</span> correspond à l'apparition de <span class=\"kw-clinique\">signes moteurs axiaux</span> peu ou pas sensibles aux traitements dopaminergiques (le processus dégénératif dépasse alors la voie nigro-striatale).</p>\n\n<table >\n  <thead>\n    <tr><th>Domaine axial</th><th>Manifestations</th><th>Risques</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-def\">Troubles bulbaires</span></strong></td>\n      <td><span class=\"kw-clinique\">Dysarthrie</span>, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">hypersialorrhée</span> (par diminution de la déglutition spontanée).</td>\n      <td><span class=\"kw-alerte\">Fausses routes</span>, <span class=\"kw-alerte\">pneumopathies d'inhalation</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Troubles de la marche</span></strong></td>\n      <td><span class=\"kw-clinique\">Réduction de la longueur des enjambées</span> ; <span class=\"kw-def\">freezing / enrayement cinétique</span> (pieds collés au sol à l'initiation, au demi-tour, au passage d'un obstacle) ; <span class=\"kw-def\">festination</span> (emballement brutal de la marche).</td>\n      <td><span class=\"kw-alerte\">Chutes vers l'avant</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Troubles de l'équilibre postural</span></strong></td>\n      <td><span class=\"kw-clinique\">Perte progressive des réflexes posturaux</span>.</td>\n      <td><span class=\"kw-alerte\">Chutes vers l'arrière</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Troubles de la posture</span></strong></td>\n      <td><span class=\"kw-clinique\">Triple flexion</span> ; <span class=\"kw-def\">camptocornie</span> (flexion du tronc vers l'avant) ; <span class=\"kw-def\">syndrome de Pise</span> (flexion latérale du tronc).</td>\n      <td>Compensation difficile, retentissement fonctionnel.</td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 109 — Trouble marche - équilibre</em></p>","frequence":1},{"id":"106-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations de la phase de déclin cognitif et comportemental","contenu":"<p>La <span class=\"kw-def\">phase de déclin cognitif et comportemental</span> regroupe les <span class=\"kw-clinique\">signes non moteurs</span> peu ou pas sensibles aux traitements dopaminergiques. Ces troubles sont <strong>fréquents aux stades avancés</strong>.</p>\n\n<table >\n  <thead>\n    <tr><th>Domaine</th><th>Manifestations</th><th><span class=\"kw-clinique\">Évolution</span> / Chiffres</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Cognition</strong></td>\n      <td><span class=\"kw-def\">Syndrome dysexécutif</span> évoluant vers une <span class=\"kw-def\">démence</span>.</td>\n      <td><span class=\"kw-chiffre\">30 %</span> des patients ; <span class=\"kw-chiffre\">80 %</span> après <span class=\"kw-chiffre\">15-20 ans</span> d'<span class=\"kw-clinique\">évolution</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Comportement</strong></td>\n      <td><span class=\"kw-clinique\">Hallucinations</span>, <span class=\"kw-clinique\">délires</span> provoqués par le traitement dopaminergique.</td>\n      <td><span class=\"kw-alerte\">Indique souvent une évolution vers un état démentiel</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Thymie</strong></td>\n      <td><span class=\"kw-clinique\">Apathie</span>, <span class=\"kw-clinique\">dépression</span>, <span class=\"kw-clinique\">anxiété</span>.</td>\n      <td>Fréquentes à tous les stades.</td>\n    </tr>\n    <tr>\n      <td><strong>Douleurs</strong></td>\n      <td>Douleurs musculo-squelettiques liées à la rigidité et aux troubles posturaux.</td>\n      <td>Sous-évaluées chez la personne vulnérable.</td>\n    </tr>\n    <tr>\n      <td><strong>Dysautonomie</strong></td>\n      <td><span class=\"kw-clinique\">HTO</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">troubles vésicosphinctériens</span> (urgenturie).</td>\n      <td>Aggravation progressive.</td>\n    </tr>\n    <tr>\n      <td><strong>Sommeil et vigilance</strong></td>\n      <td>Troubles du sommeil ; <span class=\"kw-clinique\">somnolence diurne</span>.</td>\n      <td>Cf. effets indésirables des agonistes dopaminergiques (obj-7).</td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 108 — Confusion, démence du sujet âgé · 70 — Troubles psychiques du sujet agê</em></p>","frequence":2},{"id":"106-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les différentes classes de médicaments antiparkinsoniens","contenu":"<p>Les <span class=\"kw-def\">antiparkinsoniens</span> visent à compenser le déficit dopaminergique nigro-striatal. <span class=\"kw-chiffre\">5 classes</span> principales — la <span class=\"kw-ttt\">L-DOPA</span> reste le traitement le plus efficace.</p>\n\n<table >\n  <thead>\n    <tr><th>Classe</th><th>Mécanisme et molécules</th><th>Intérêt</th><th>Effets indésirables</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-ttt\">L-DOPA</span></strong></td>\n      <td>\n        <strong>Mécanisme :</strong> précurseur de la <span class=\"kw-ttt\">dopamine</span>, transformé en <span class=\"kw-ttt\">dopamine</span> intracérébrale par la <span class=\"kw-def\">dopa-décarboxylase (DDC)</span> ;<br>\n        <strong>Association :</strong> <span class=\"kw-ttt\">carbidopa</span> ou <span class=\"kw-ttt\">bensérazide</span> (inhibiteurs de la DDC périphérique) ;<br>\n        <strong>Absorption :</strong> au niveau <span class=\"kw-clinique\">intestinal</span>.\n      </td>\n      <td><span class=\"kw-clinique\">Traitement le plus efficace</span> sur la symptomatologie parkinsonienne et le mieux toléré.</td>\n      <td><strong>Périphériques :</strong> <span class=\"kw-clinique\">hypotension orthostatique</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Agonistes dopaminergiques LP</strong></td>\n      <td>\n        <strong>Mécanisme :</strong> action directe sur les récepteurs dopaminergiques (sans synthèse de <span class=\"kw-ttt\">dopamine</span>) ;<br>\n        <strong>Molécules :</strong> <span class=\"kw-ttt\">pramipexole</span>, <span class=\"kw-ttt\">ropinirole</span>, <span class=\"kw-ttt\">rotigotine</span>, <span class=\"kw-ttt\">piribédil</span>, <span class=\"kw-ttt\">apomorphine</span>.\n      </td>\n      <td>Retardent les complications motrices en <span class=\"kw-clinique\">phase précoce</span> ; action moins puissante que la L-DOPA.</td>\n      <td>\n        <strong>Périphériques :</strong> <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">HTO</span> (plus fréquents que sous L-DOPA) ;<br>\n        <strong>Comportementaux :</strong> <span class=\"kw-alerte\">troubles du contrôle des impulsions</span> (<span class=\"kw-chiffre\">20 %</span>) — jeu pathologique, troubles alimentaires, achats compulsifs, hypersexualité, collectionnisme (prudence si ATCD d'addiction) ;<br>\n        <strong>Psychiatriques :</strong> <span class=\"kw-clinique\">hallucinations</span> ;<br>\n        <strong>Vigilance :</strong> <span class=\"kw-clinique\">somnolence diurne</span>, <span class=\"kw-alerte\">attaques d'endormissement</span> (risque d'accident au volant) ;<br>\n        <strong>Autres :</strong> <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>.<br>\n        <em>Effets secondaires réversibles à l'arrêt / diminution du traitement.</em>\n      </td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-ttt\">IMAO-B</span></strong></td>\n      <td>\n        <strong>Mécanisme :</strong> inhibition de la monoamine oxydase de type B → inhibition du métabolisme de la <span class=\"kw-ttt\">dopamine</span> ;<br>\n        <strong>Molécule :</strong> <span class=\"kw-ttt\">rasagiline</span>.\n      </td>\n      <td>Action dopaminergique modérée.</td>\n      <td>Habituellement bien tolérée.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-ttt\">ICOMT</span></strong></td>\n      <td><strong>Mécanisme :</strong> inhibition de la catéchol-O-méthyltransférase → diminution du métabolisme périphérique de la L-DOPA, prolongation de son action.</td>\n      <td>Prolonge l'action de la L-DOPA en cas de fluctuations.</td>\n      <td><span class=\"kw-clinique\">Diarrhée</span>, coloration des urines.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-ttt\">Amantadine</span></strong></td>\n      <td><strong>Mécanisme :</strong> action anti-glutamatergique.</td>\n      <td><span class=\"kw-clinique\">Effet antidyskinétique</span> — utilisée pour le traitement des dyskinésies de la phase tardive.</td>\n      <td><span class=\"kw-clinique\">Œdèmes</span>, livedo, troubles de la vigilance.</td>\n    </tr>\n  </tbody>\n</table>","frequence":2},{"id":"106-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les thérapeutiques non médicamenteuses et l’importance de la kinésithérapie","contenu":"<p>Les <span class=\"kw-def\">thérapeutiques non médicamenteuses</span> sont un pilier de la prise en charge. La <span class=\"kw-def\">kinésithérapie</span> est essentielle à tous les stades — <strong>à pratiquer le matin avant la 1<sup>re</sup> prise de lévodopa</strong>, avec recherche d'une fatigue à chaque exercice pour une efficacité optimale.</p>\n\n<table >\n  <thead>\n    <tr><th>Axe</th><th>Précisions</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Social</strong></td>\n      <td>\n        Demande d'<span class=\"kw-def\">ALD</span> ;<br>\n        Demande de <span class=\"kw-clinique\">reconnaissance professionnelle</span> chez les sujets exposés aux pesticides.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Kinésithérapie</strong></td>\n      <td>\n        Enseignement d'une <span class=\"kw-clinique\">gymnastique quotidienne</span>, prévention des complications musculo-squelettiques, travail de l'équilibre postural, apprentissage des transferts. <em>Programme détaillé selon le <span class=\"kw-def\">stade</span> ci-dessous.</em>\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Orthophonie</strong></td>\n      <td>En cas de <span class=\"kw-clinique\">dysarthrie</span> et de <span class=\"kw-clinique\">troubles de la déglutition</span> ; techniques LSVT (Lee Silverman Voice Therapy), travail de la déglutition au miroir.</td>\n    </tr>\n    <tr>\n      <td><strong>Soutien</strong></td>\n      <td>Associations de patients (information patient et aidants).</td>\n    </tr>\n    <tr>\n      <td><strong>Neurochirurgie</strong></td>\n      <td>\n        <span class=\"kw-def\">Stimulation cérébrale profonde à haute fréquence</span> du <span class=\"kw-def\">noyau sous-thalamique</span> ou du <span class=\"kw-def\">pallidum interne</span> — option de recours en cas d'échec du traitement <span class=\"kw-etio\">médicamenteux</span>.<br>\n        <strong>Indications cumulatives :</strong>\n        <ul style=\"margin:0.4rem 0 0;\">\n          <li>Patient âgé de <span class=\"kw-chiffre\">&lt; 70 ans</span> ;</li>\n          <li><span class=\"kw-clinique\">Complications motrices sévères</span> (fluctuations, dyskinésies) ou <span class=\"kw-clinique\">tremblement handicapant</span> malgré un traitement bien conduit ;</li>\n          <li><span class=\"kw-ci\">Absence de troubles cognitifs ou comportementaux sévères</span>.</li>\n        </ul>\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<h4>Programme de kinésithérapie selon le <span class=\"kw-def\">stade</span></h4>\n<table >\n  <thead>\n    <tr><th>Objectif</th><th>Stade débutant à modéré <em>(déambulation autonome)</em></th><th>Stade avancé <em>(déambulation altérée ou cognition limitante)</em></th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Optimisation dopaminergique</strong></td>\n      <td>Travail physique <strong>avant</strong> la prise de lévodopa → meilleure production / disponibilité endogène + meilleure absorption / utilisation striatale de la L-DOPA exogène.</td>\n      <td>Idem si la coopération du patient le permet.</td>\n    </tr>\n    <tr>\n      <td><strong>Travail moteur</strong></td>\n      <td>\n        <span class=\"kw-clinique\">Reconditionnement à l'effort</span> : travail aérobie à <span class=\"kw-clinique\">haute intensité</span> ;<br>\n        Renforcement contre résistance (membres + extenseurs paravertébraux) ;<br>\n        Travail de marche centré sur la <span class=\"kw-clinique\">longueur du pas</span> (et non la vitesse) ;<br>\n        <span class=\"kw-clinique\">Travail en double tâche</span> cognitive + motrice (diminue freezing) ;<br>\n        Travail dissociation axiale, transferts assis-debout sur chaises de hauteur décroissante, retournements au sol.\n      </td>\n      <td>\n        Travail de la <span class=\"kw-clinique\">capacité respiratoire</span> ;<br>\n        Renforcement des <span class=\"kw-clinique\">extenseurs paravertébraux</span> (préservation de la statique rachidienne) ;<br>\n        <span class=\"kw-clinique\">Mobilisations articulaires passives</span>, postures d'étirement (préservation orthopédique).\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Phonation et déglutition</strong></td>\n      <td>Travail d'ampliation thoracique, praxies bucco-faciales, technique LSVT ; remplacement possible par le <span class=\"kw-clinique\">chant</span> ou la <span class=\"kw-clinique\">chorale</span>.</td>\n      <td>Masqueurs de voix, manger / boire face à un <span class=\"kw-clinique\">miroir</span>, déglutition en orthophonie.</td>\n    </tr>\n    <tr>\n      <td><strong>Prévention des chutes</strong></td>\n      <td>Signaux sensoriels (acoustiques — métronome, visuels — barres au sol, émotionnels — travail de groupe).</td>\n      <td>\n        Demi-tours en <span class=\"kw-clinique\">arc de cercle</span> ;<br>\n        Stratégies anti-freezing (<em>« stop et un grand pas seulement »</em>) ;<br>\n        Modification de l'environnement (chaises surélevées, draps satin/coton) ;<br>\n        Éviter les tâches simultanées ;<br>\n        <span class=\"kw-ci\">Préférer la canne simple</span> au déambulateur (le déambulateur déconditionne les réactions d'équilibre antéropostérieur).\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Compléments</strong></td>\n      <td>Taï-chi thérapeutique, danses, yoga thérapeutique.</td>\n      <td>—</td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 138 — Douleur chez la personne vulnérable · 130 — Personne âgée malade</em></p>","frequence":4},{"id":"106-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement à la phase initiale de la maladie","contenu":"<p>Le choix du traitement initial dépend de <strong>l'âge du patient</strong> et de la <strong>gêne fonctionnelle</strong>. Un antiémétique préventif est prescrit en cas de <span class=\"kw-clinique\">nausées</span> / <span class=\"kw-clinique\">vomissements</span> à l'instauration.</p>\n\n<table >\n  <thead>\n    <tr><th>Ligne thérapeutique</th><th>Avant <span class=\"kw-chiffre\">65-70 ans</span></th><th>Après <span class=\"kw-chiffre\">65-70 ans</span></th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>1<sup>re</sup> intention</strong></td>\n      <td>\n        <strong>Option 1 :</strong> <span class=\"kw-ttt\">agoniste dopaminergique LP</span> en monothérapie ;<br>\n        <strong>Option 2 :</strong> <span class=\"kw-ttt\">IMAO-B</span> ;<br>\n        <strong>Option 3 :</strong> association <span class=\"kw-ttt\">agoniste dopaminergique LP + IMAO-B</span> ;<br>\n        <strong>Option 4 :</strong> <span class=\"kw-ttt\">L-DOPA + inhibiteur de DDC</span> si handicap moteur et altération de la qualité de vie.\n      </td>\n      <td>\n        <strong>Option 1 :</strong> <span class=\"kw-ttt\">L-DOPA + inhibiteur de DDC</span> ;<br>\n        <strong>Option 2 :</strong> <span class=\"kw-ttt\">IMAO-B</span>.\n      </td>\n    </tr>\n    <tr>\n      <td><strong>2<sup>nd</sup> intention</strong> <em>(contrôle insuffisant)</em></td>\n      <td>\n        Augmenter les posologies des agonistes dopaminergiques ;<br>\n        Si agonistes mal tolérés ou inefficaces : associer à <span class=\"kw-ttt\">L-DOPA</span> ou à <span class=\"kw-ttt\">IMAO-B</span>.\n      </td>\n      <td>\n        Augmenter la posologie de <span class=\"kw-ttt\">L-DOPA</span> ;<br>\n        Associer <span class=\"kw-ttt\">L-DOPA + inhibiteur de DDC + IMAO-B</span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<h4>Prévention des <span class=\"kw-clinique\">nausées</span> / <span class=\"kw-clinique\">vomissements</span> à l'instauration</h4>\n<p><span class=\"kw-ttt\">Dompéridone</span> (neuroleptique butyrophénone) — stimule la motilité gastrique, passe peu la barrière hémato-encéphalique → effets centraux plus rares que le <span class=\"kw-ttt\">métoclopramide</span>, mais <strong>mêmes effets sur la sécrétion de <span class=\"kw-clinique\">prolactine</span></strong>.</p>\n<ul>\n  <li><strong>Posologie :</strong> <span class=\"kw-chiffre\">10-80 mg/j</span> per os ou sublingual ;</li>\n  <li><strong>Durée :</strong> <span class=\"kw-clinique\">maximum 7 jours</span> ;</li>\n  <li><strong><span class=\"kw-ci\">Contre-indication :</span></strong> <span class=\"kw-alerte\">allongement du QTc</span>.</li>\n</ul>","frequence":3},{"id":"106-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","contenu":"<p>Le <span class=\"kw-etio\">syndrome parkinsonien iatrogène</span> est dû au blocage des récepteurs dopaminergiques par certains médicaments. Il est <strong>réversible à l'arrêt du médicament</strong>, mais peut démasquer une maladie de Parkinson sous-jacente.</p>\n\n<table >\n  <thead>\n    <tr><th>Médicaments en cause</th><th>Caractéristiques cliniques</th><th>Conduite à tenir</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>\n        <strong><span class=\"kw-ttt\">Neuroleptiques</span> ++</strong> (toutes générations) ;<br>\n        <strong>Neuroleptiques cachés :</strong> <span class=\"kw-ttt\">métoclopramide</span> ; <span class=\"kw-ttt\">métopimazine</span> ; <span class=\"kw-ttt\">flunarizine</span> ; <span class=\"kw-ttt\">alimémazine</span> ; <span class=\"kw-ttt\">méquitazine</span> ; <span class=\"kw-ttt\">trimétazidine</span> ; <span class=\"kw-ttt\">lithium</span> ; <span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">valproate</span>.\n      </td>\n      <td>\n        <strong>Latéralité :</strong> syndrome plutôt symétrique (caractéristique inconstante) ;<br>\n        <strong>Tremblement :</strong> postural ou d'action plus fréquent qu'un authentique tremblement de repos ;<br>\n        <strong>Mouvements anormaux associés :</strong> <span class=\"kw-clinique\">dyskinésies bucco-linguo-faciales</span> possibles ;<br>\n        <strong>Réponse au traitement :</strong> <span class=\"kw-alerte\">absence de réponse au traitement dopaminergique</span>.\n      </td>\n      <td>\n        <strong>1.</strong> Arrêter le neuroleptique en cause si possible ;<br>\n        <strong>2.</strong> Si impossible, remplacer par un neuroleptique atypique à faibles effets extrapyramidaux :<br>\n        — <span class=\"kw-ttt\">Clozapine</span> : risque d'<span class=\"kw-alerte\">agranulocytose</span> → <span class=\"kw-bio\">NFS hebdomadaire pendant 18 semaines</span>, puis mensuelle tant que le traitement est poursuivi ;<br>\n        — <span class=\"kw-ttt\">Quétiapine</span> ;<br>\n        <strong>3.</strong> Si modifications impossibles : correcteur <span class=\"kw-ttt\">anticholinergique</span> (ex. <span class=\"kw-ttt\">tropatépine</span> per os) — <span class=\"kw-ci\">jamais en prescription d'emblée en association aux antipsychotiques</span>.\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p class=\"obj-renvois\"><em>📎 Items liés : 65 — Trouble délirant persistant</em></p>","frequence":2},{"id":"106-12","rang":"A","rubrique":"Contenu multimédia","titre":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","contenu":"<p>Face à un patient ou une vidéo, l'orientation vers une <span class=\"kw-def\">maladie de Parkinson</span> repose sur l'observation d'une <strong>triade clinique asymétrique</strong> et l'absence de <span class=\"kw-alerte\">drapeaux rouges</span>. Voici la grille d'observation.</p>\n\n<table >\n  <thead>\n    <tr><th>Élément à rechercher</th><th>Ce qui oriente VERS une MP</th><th>Ce qui oriente CONTRE</th></tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td><strong>Latéralité</strong></td>\n      <td><span class=\"kw-clinique\">Asymétrie</span> ou <span class=\"kw-clinique\">unilatéralité</span> du syndrome (persistante).</td>\n      <td><span class=\"kw-alerte\">Syndrome strictement symétrique</span> (évoquer <span class=\"kw-etio\">iatrogène</span> ou <span class=\"kw-etio\">vasculaire</span>).</td>\n    </tr>\n    <tr>\n      <td><strong>Visage</strong></td>\n      <td><span class=\"kw-clinique\">Hypomimie</span>, raréfaction du <span class=\"kw-clinique\">clignement</span>.</td>\n      <td><span class=\"kw-alerte\">Mouvements oculaires anormaux</span> évoquant une <span class=\"kw-def\">PSP</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Voix</strong></td>\n      <td><span class=\"kw-clinique\">Voix monocorde et monotone</span>.</td>\n      <td><span class=\"kw-alerte\">Dysarthrie pseudo-bulbaire précoce</span> (<span class=\"kw-alerte\">drapeau rouge</span> — PSP, AMS).</td>\n    </tr>\n    <tr>\n      <td><strong>Écriture (si demandée)</strong></td>\n      <td><span class=\"kw-clinique\">Micrographie</span> (<span class=\"kw-ttt\">réduction</span> progressive de la taille des lettres).</td>\n      <td><span class=\"kw-alerte\">Tremblement d'action isolé</span> (<span class=\"kw-etio\">tremblement essentiel</span>).</td>\n    </tr>\n    <tr>\n      <td><strong>Membre supérieur — gestes alternatifs rapides</strong></td>\n      <td><span class=\"kw-clinique\">Opposition pouce-index lente et décrémentielle</span>.</td>\n      <td><span class=\"kw-alerte\">Maladresse cérébelleuse</span> (<span class=\"kw-clinique\">dysmétrie au doigt-nez</span>).</td>\n    </tr>\n    <tr>\n      <td><strong>Marche</strong></td>\n      <td><span class=\"kw-clinique\">Petits pas</span>, <span class=\"kw-clinique\">perte du ballant du bras</span> du côté atteint.</td>\n      <td><span class=\"kw-alerte\">Marche à grands pas</span>, <span class=\"kw-alerte\">ataxie cérébelleuse</span>, <span class=\"kw-alerte\">fauchage</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Repos</strong></td>\n      <td><span class=\"kw-clinique\">Tremblement de repos</span> distal (lèvres, menton, main) à <span class=\"kw-chiffre\">4-6 Hz</span>, disparaissant à l'action.</td>\n      <td><span class=\"kw-alerte\">Tremblement majoré à l'action</span> (<span class=\"kw-etio\">tremblement essentiel</span>), <span class=\"kw-alerte\">tremblement du chef</span> (cérébelleux).</td>\n    </tr>\n    <tr>\n      <td><strong>Tonus passif</strong></td>\n      <td><span class=\"kw-clinique\">Rigidité plastique en roue dentée</span>, sensibilisée par la <span class=\"kw-clinique\">manœuvre de Froment</span>.</td>\n      <td><span class=\"kw-alerte\">Spasticité</span> (cède d'un coup), <span class=\"kw-alerte\">rigidité de décérébration</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Réflexes posturaux</strong></td>\n      <td><span class=\"kw-clinique\">Conservés au début</span>, altérés tardivement.</td>\n      <td><span class=\"kw-alerte\">Chutes précoces</span> = <span class=\"kw-alerte\">drapeau rouge</span> (<span class=\"kw-def\">PSP</span>, <span class=\"kw-def\">MSA</span>).</td>\n    </tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-info\">\n  <strong>À retenir.</strong> Une fois la triade observée et l'<span class=\"kw-clinique\">asymétrie</span> confirmée, l'examen neurologique <strong>doit être normal en dehors du syndrome parkinsonien</strong>. Toute anomalie associée (cérébelleux, pyramidal, corticale, oculomotrice) est un <span class=\"kw-alerte\">drapeau rouge</span> (cf. obj-3).\n</div>\n\n<p class=\"obj-renvois\"><em>📎 Items liés : 107 — Mouvements anormaux · 109 — Trouble marche - équilibre · 91 — Déficit neuro récent</em></p>","frequence":0}],"astuces":[{"type":"danger","titre":"Neuroleptiques INTERDITS chez le parkinsonien","contenu":"Aucun neuroleptique classique (halopéridol, rispéridone, olanzapine) ne doit être prescrit à un parkinsonien — risque d'aggravation majeure et de syndrome malin. Seules la clozapine (surveillance NFS) et la quétiapine sont utilisables. Pour les nausées : dompéridone (PAS de métoclopramide-Primpéran®, qui est un neuroleptique caché)."},{"type":"danger","titre":"Troubles du contrôle des impulsions (TCI) sous agonistes","contenu":"Jeu pathologique, hypersexualité, achats compulsifs, hyperphagie : 3-15 % des patients sous agonistes dopaminergiques (ropinirole, pramipexole, rotigotine). À RECHERCHER ACTIVEMENT à chaque consultation (le patient et la famille n'en parlent pas spontanément). PEC = réduction/arrêt de l'agoniste, pas la L-dopa."},{"type":"warn","titre":"Asymétrie = argument fort en faveur de la MP","contenu":"Un syndrome parkinsonien BILATÉRAL ET SYMÉTRIQUE d'emblée doit faire évoquer un syndrome atypique (AMS, PSP, parkinsonisme iatrogène, vasculaire) ou une cause secondaire. La MP idiopathique est presque toujours asymétrique au début (et le reste partiellement même au stade évolué)."},{"type":"warn","titre":"Chutes précoces = drapeau rouge majeur","contenu":"Des chutes répétées dans les 3 premières années d'évolution évoquent une PSP (paralysie supranucléaire progressive — recherche paralysie verticale du regard vers le bas) ou une AMS. Dans la MP idiopathique, les chutes apparaissent typiquement après 7-10 ans d'évolution. À explorer impérativement par IRM cérébrale."},{"type":"tip","titre":"TCSP = signe prodromal puissant","contenu":"Le trouble du comportement en sommeil paradoxal (TCSP — agitation motrice et vocalisations pendant les rêves) est associé à un risque ≥ 80 % de développer une synucléinopathie (MP, DCL, AMS) dans les 15 ans. À rechercher dans l'anamnèse de tout sujet > 50 ans, et à suivre en consultation neurologique spécialisée si présent."},{"type":"info","titre":"Pesticides = maladie professionnelle (tableau n°58)","contenu":"La MP est reconnue maladie professionnelle chez les agriculteurs exposés aux pesticides depuis 2012 (tableau n°58 du régime agricole). Penser à la déclaration en MP si profession agricole — ouvre droits à une indemnisation et à une prise en charge à 100 %."}],"strategie":{"hospit":"<p><strong><span class=\"kw-def\">Suivi</span> ambulatoire spécialisé</strong></p><ul><li><span class=\"kw-def\">Maladie de Parkinson</span> = affection chronique suivie en <span class=\"kw-ttt\">consultation de neurologie</span></li><li>Diagnostic <span class=\"kw-clinique\">clinique</span> : <span class=\"kw-alerte\">aucune paraclinique</span> si présentation typique, pas d'<span class=\"kw-alerte\">hospitalisation</span> pour le diagnostic</li></ul><p><strong>Prise en charge multidisciplinaire</strong></p><ul><li><span class=\"kw-ttt\">Kinésithérapie</span> (à tous les stades)</li><li><span class=\"kw-ttt\">Orthophonie</span> si <span class=\"kw-clinique\">dysarthrie</span> / <span class=\"kw-clinique\">troubles de la déglutition</span></li><li><span class=\"kw-ttt\">Ergothérapie</span> · associations de patients (soutien des patients et des aidants)</li></ul><p><strong>Démarches médico-sociales</strong></p><ul><li>Demande d'<span class=\"kw-def\">ALD</span></li><li>Demande de <span class=\"kw-def\">reconnaissance en maladie professionnelle</span> si exposition aux <span class=\"kw-etio\">pesticides</span></li></ul>","redflags":"<p><strong>Sens :</strong> ce sont des <span class=\"kw-def\">drapeaux rouges diagnostiques</span> — leur présence va à l'encontre de la maladie de Parkinson et oriente vers un <span class=\"kw-etio\">syndrome parkinsonien atypique ou secondaire</span>.</p><ul><li><span class=\"kw-alerte\">Absence de réponse prolongée au traitement dopaminergique</span></li><li><span class=\"kw-alerte\">Syndrome cérébelleux</span>, <span class=\"kw-alerte\">atteinte pyramidale</span> ou <span class=\"kw-alerte\">troubles oculomoteurs</span></li><li><span class=\"kw-alerte\">Signes corticaux</span> : <span class=\"kw-clinique\">aphasie</span>, <span class=\"kw-clinique\">apraxie</span>, <span class=\"kw-clinique\">myoclonies</span>, <span class=\"kw-clinique\">astéréognosie</span></li><li><span class=\"kw-alerte\">Progression rapide</span> avec <span class=\"kw-alerte\">chutes précoces</span></li><li>Précocité d'une <span class=\"kw-alerte\">atteinte cognitive</span>, d'un <span class=\"kw-alerte\">syndrome pseudo-bulbaire</span> (<span class=\"kw-clinique\">dysarthrie</span>, <span class=\"kw-clinique\">dysphagie</span>) ou d'une <span class=\"kw-alerte\">dysautonomie</span></li><li><span class=\"kw-alerte\">Syndrome parkinsonien symétrique</span> (la maladie de Parkinson est <span class=\"kw-clinique\">asymétrique</span>)</li><li>Tout syndrome parkinsonien chez un sujet <span class=\"kw-chiffre\">&lt; 40 ans</span> → rechercher une <span class=\"kw-etio\">maladie de Wilson</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> traitement <span class=\"kw-clinique\">symptomatique</span> (pas curatif) reposant sur la <span class=\"kw-ttt\">restauration dopaminergique</span> ; le choix de la 1ʳᵉ molécule dépend de l'<span class=\"kw-clinique\">âge</span> et du retentissement, et la <span class=\"kw-ttt\">kinésithérapie</span> est essentielle à tous les stades.</p><p><strong>Avant <span class=\"kw-chiffre\">65-70 ans</span> <span class=\"q\">— 1ʳᵉ intention</span></strong></p><p><span class=\"kw-ttt\">L-DOPA + inhibiteur de la DDC</span> (carbidopa/bensérazide) d'emblée si <span class=\"kw-clinique\">handicap moteur</span> et <span class=\"kw-clinique\">altération de la qualité de vie</span></p><ul><li><span class=\"kw-ttt\">Agoniste dopaminergique LP</span> en monothérapie (pramipexole, ropinirole, rotigotine, piribédil), seul ou associé à un <span class=\"kw-ttt\">IMAO-B</span> (rasagiline)</li><li><span class=\"kw-ttt\">IMAO-B</span> seul possible</li></ul><p><strong>Après <span class=\"kw-chiffre\">65-70 ans</span> <span class=\"q\">— 1ʳᵉ intention</span></strong></p><ul><li><span class=\"kw-ttt\">L-DOPA + inhibiteur de la DDC</span></li><li>ou <span class=\"kw-ttt\">IMAO-B</span></li></ul><p><strong>Rééducation <span class=\"q\">— à tous les stades</span></strong></p><ul><li><span class=\"kw-ttt\">Kinésithérapie</span> quotidienne, de préférence le <span class=\"kw-chiffre\">matin avant la 1ʳᵉ prise de lévodopa</span></li><li>Travail <span class=\"kw-clinique\">aérobie</span> à haute intensité, double tâche, prévention des <span class=\"kw-clinique\">chutes</span></li><li><span class=\"kw-ttt\">Orthophonie</span> si <span class=\"kw-clinique\">dysarthrie</span> / <span class=\"kw-clinique\">troubles de la déglutition</span></li></ul><p><strong>Stades avancés <span class=\"q\">— fluctuations & dyskinésies</span></strong></p><ul><li>Fluctuations : <span class=\"kw-ttt\">fractionnement de la L-DOPA</span>, association / augmentation des <span class=\"kw-ttt\">agonistes dopaminergiques</span>, <span class=\"kw-ttt\">ICOMT</span>, <span class=\"kw-ttt\">IMAO-B</span></li><li>Dyskinésies : réduire / fractionner la <span class=\"kw-ttt\">L-DOPA</span> ; <span class=\"kw-ttt\">amantadine</span> (effet anti-dyskinétique)</li><li>Blocages sévères : <span class=\"kw-ttt\">apomorphine</span> (stylo ou pompe SC), <span class=\"kw-ttt\">L-DOPA intraduodénale</span> par gastrostomie</li></ul><p><strong>Stimulation cérébrale profonde (SCP)</strong></p><p>indiquée si <span class=\"kw-chiffre\">&lt; 70 ans</span>, <span class=\"kw-alerte\">complications motrices sévères</span> ou tremblement handicapant malgré un traitement bien conduit, et <span class=\"kw-alerte\">absence de troubles cognitifs / comportementaux sévères</span></p><ul><li>Stimulation à haute fréquence du <span class=\"kw-def\">noyau sous-thalamique</span> ou du <span class=\"kw-def\">pallidum interne</span></li></ul><p><strong>Syndrome parkinsonien <span class=\"kw-etio\">iatrogène</span></strong></p><ul><li><span class=\"kw-ttt\">Arrêt du neuroleptique</span> en cause si possible</li><li>Si impossible : <span class=\"kw-ttt\">neuroleptique atypique</span> — <span class=\"kw-ttt\">clozapine</span> (<span class=\"kw-alerte\">risque d'agranulocytose</span> → <span class=\"kw-bio\">NFS</span> hebdomadaire <span class=\"kw-chiffre\">18 semaines</span> puis mensuelle) ou <span class=\"kw-ttt\">quétiapine</span></li><li><span class=\"kw-ci\">Anticholinergique jamais prescrit d'emblée</span> en association aux antipsychotiques</li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> sous traitement</strong></p><ul><li>Phase de bon contrôle (« <span class=\"kw-def\">lune de miel</span> »)</li><li>Puis <span class=\"kw-def\">complications motrices</span> du traitement dopaminergique (<span class=\"kw-chiffre\">4-5 ans</span>) : fluctuations d'efficacité, dyskinésies</li><li>Puis phase de <span class=\"kw-def\">déclin moteur et cognitif</span> : signes <span class=\"kw-alerte\">peu ou pas sensibles au traitement dopaminergique</span></li></ul><p><strong>Complications motrices à dépister</strong></p><ul><li>Fluctuations : <span class=\"kw-clinique\">akinésie de fin de dose</span> / de nuit, <span class=\"kw-clinique\">phénomène ON/OFF</span></li><li>Dyskinésies de <span class=\"kw-clinique\">milieu / pic de dose</span> (choréiques) ou <span class=\"kw-clinique\">biphasiques</span> (dystoniques, douloureuses)</li></ul><p><strong>Signes non moteurs à surveiller</strong></p><ul><li><span class=\"kw-clinique\">Troubles cognitifs</span> (syndrome dysexécutif → démence : <span class=\"kw-chiffre\">30 %</span>, jusqu'à <span class=\"kw-chiffre\">80 %</span> après <span class=\"kw-chiffre\">15-20 ans</span>)</li><li><span class=\"kw-clinique\">Hallucinations</span> / <span class=\"kw-clinique\">délires</span> induits par le traitement dopaminergique (peuvent annoncer une <span class=\"kw-clinique\">évolution</span> démentielle)</li><li><span class=\"kw-clinique\">Dysautonomie</span> : <span class=\"kw-clinique\">HTO</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">urgenturie</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span> du traitement</strong></p><ul><li>Efficacité et tolérance ; <span class=\"kw-clinique\">troubles du contrôle des impulsions</span> (jeu pathologique, achats compulsifs, hypersexualité) sous <span class=\"kw-ttt\">agonistes dopaminergiques</span></li><li><span class=\"kw-clinique\">Nausées</span> / vomissements à l'initiation : <span class=\"kw-ttt\">dompéridone</span> (<span class=\"kw-ci\">CI si allongement du QTc</span>), <span class=\"kw-chiffre\">≤ 7 jours</span></li><li><span class=\"kw-bio\">NFS</span> hebdomadaire <span class=\"kw-chiffre\">18 semaines</span> puis mensuelle sous <span class=\"kw-ttt\">clozapine</span></li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/maladie-de-parkinson","label":"Collège CEN — Maladie de Parkinson"},{"href":"https://radiopaedia.org/articles/parkinson-disease-1","label":"Radiopaedia : Parkinson disease"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Syndrome parkinsonien confirmé — Bradykinésie + rigidité plastique et/ou tremblement de repos","detail":"<h4>Tri du syndrome parkinsonien — Maladie de Parkinson <span class=\"kw-bio\">vs</span> syndromes parkinsoniens atypiques / secondaires</h4>","branches":[{"to":"t-iatrogene","label":"Prise de neuroleptiques ou de neuroleptiques cachés (syndrome symétrique, tremblement d'action, non dopa-sensible)","color":"blue"},{"to":"q-age","label":"Pas de cause iatrogène","color":"blue"}]},{"id":"t-iatrogene","kind":"terminal","label":"Syndrome parkinsonien iatrogène","color":"blue","detail":"<h4>Clinique</h4><ul><li>Syndrome plutôt <span class=\"kw-clinique\">symétrique</span> (caractère inconstant)</li><li><span class=\"kw-clinique\">Tremblement postural ou d'action</span> plus qu'un tremblement de repos</li><li><span class=\"kw-clinique\">Dyskinésies bucco-linguo-faciales</span> possibles</li><li><span class=\"kw-alerte\">Absence de réponse au traitement dopaminergique</span></li></ul><h4>Médicaments en cause</h4><ul><li><span class=\"kw-etio\">Neuroleptiques</span> ++</li><li><span class=\"kw-etio\">Neuroleptiques cachés</span> : <span class=\"kw-ttt\">métoclopramide</span>, métopimazine, flunarizine, alimémazine, méquitazine, trimétazidine, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">amiodarone</span>, <span class=\"kw-ttt\">valproate</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Arrêt du neuroleptique</span> en cause si possible</li><li>Sinon : <span class=\"kw-ttt\">clozapine</span> (<span class=\"kw-bio\">NFS</span> hebdomadaire <span class=\"kw-chiffre\">18 semaines</span>, <span class=\"kw-alerte\">agranulocytose</span>) ou <span class=\"kw-ttt\">quétiapine</span></li><li><span class=\"kw-ci\">Anticholinergique jamais d'emblée</span> en association aux antipsychotiques</li></ul>"},{"id":"q-age","kind":"decision","label":"Âge inférieur à 40 ans ?","branches":[{"to":"t-wilson","label":"Oui — sujet jeune","color":"amber"},{"to":"q-typique","label":"Non (40 ans ou plus)","color":"blue"}]},{"id":"t-wilson","kind":"terminal","label":"Rechercher une maladie de Wilson","color":"amber","detail":"<h4>Dogme</h4><ul><li>Tout syndrome parkinsonien ou mouvement anormal involontaire chez un sujet <span class=\"kw-chiffre\">&lt; 40 ans</span> doit faire rechercher une <span class=\"kw-etio\">maladie de Wilson</span> (transmission <span class=\"kw-def\">autosomique récessive</span>, mutation <span class=\"kw-def\">ATP7B</span>)</li></ul><h4>Clinique</h4><ul><li>Syndrome parkinsonien, <span class=\"kw-clinique\">tremblement en « battement d'ailes »</span>, <span class=\"kw-clinique\">dystonie</span> (« rire sardonique »)</li><li><span class=\"kw-clinique\">Atteinte hépatique</span> (<span class=\"kw-clinique\">hépatomégalie</span>, hépatite, cirrhose), <span class=\"kw-clinique\">troubles psychiatriques</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Bilan cuprique</span> : <span class=\"kw-bio\">céruléoplasmine</span> ↓, cuivre sérique total ↓, <span class=\"kw-bio\">cuivre libre</span> ↑, <span class=\"kw-bio\">cuprurie des 24 h</span> ↑</li><li>Lampe à fente : <span class=\"kw-clinique\">anneau de Kayser-Fleischer</span></li><li><span class=\"kw-imagerie\">IRM cérébrale</span> : hypersignal T2 / FLAIR des noyaux gris centraux</li><li>Test <span class=\"kw-etio\">génétique</span> (après consentement)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chélateur</span> (D-pénicillamine, trientine) à la phase aiguë</li><li><span class=\"kw-ttt\">Acétate de zinc</span> en entretien à vie</li></ul>"},{"id":"q-typique","kind":"decision","label":"Présentation typique de maladie de Parkinson ? — Syndrome asymétrique + réponse au traitement dopaminergique + reste de l'examen neurologique normal (aucun drapeau rouge)","branches":[{"to":"t-parkinson","label":"Oui","color":"green"},{"to":"q-atypie","label":"Non — drapeaux rouges présents","color":"amber"}]},{"id":"t-parkinson","kind":"terminal","label":"Maladie de Parkinson","color":"green","detail":"<h4>Arguments diagnostiques</h4><ul><li>Apparition <span class=\"kw-clinique\">progressive</span> d'une <span class=\"kw-clinique\">bradykinésie</span> + rigidité plastique et/ou tremblement de repos</li><li><span class=\"kw-clinique\">Asymétrie</span> persistante du syndrome</li><li>Absence de <span class=\"kw-alerte\">drapeau rouge</span> et de cause <span class=\"kw-etio\">iatrogène</span></li><li><span class=\"kw-alerte\">Nette réduction des signes moteurs</span> sous traitement dopaminergique, prolongée (<span class=\"kw-chiffre\">&gt; 5 ans</span>)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-alerte\">Aucune imagerie</span> si présentation typique (diagnostic <span class=\"kw-clinique\">clinique</span>)</li><li><span class=\"kw-imagerie\">DaTSCAN</span> / <span class=\"kw-imagerie\">PET à la fluorodopa</span> si doute avec un tremblement essentiel</li></ul><h4>Traitement</h4><ul><li>Restauration <span class=\"kw-ttt\">dopaminergique</span> adaptée à l'âge + <span class=\"kw-ttt\">kinésithérapie</span> (cf. onglet « Stratégie de prise en charge »)</li></ul>"},{"id":"q-atypie","kind":"decision","label":"Profil des signes associés ?","branches":[{"to":"t-vasculaire","label":"Lésions vasculaires (syndrome symétrique des membres inférieurs, freezing précoce, peu dopa-sensible)","color":"blue"},{"to":"t-atypique","label":"Signes dégénératifs atypiques (cérébelleux / pyramidal / dysautonomie / oculomoteurs)","color":"amber"}]},{"id":"t-vasculaire","kind":"terminal","label":"Syndrome parkinsonien vasculaire","color":"blue","detail":"<h4>Cause</h4><ul><li><span class=\"kw-etio\">Lésions vasculaires multiples</span> des noyaux gris centraux ou de la substance blanche</li></ul><h4>Clinique</h4><ul><li>Syndrome plutôt <span class=\"kw-clinique\">symétrique</span>, <span class=\"kw-alerte\">peu sensible au traitement dopaminergique</span></li><li>Prédominance aux <span class=\"kw-clinique\">membres inférieurs</span> (lower body parkinsonism), <span class=\"kw-clinique\">freezing précoce</span></li><li><span class=\"kw-clinique\">Syndrome pseudo-bulbaire</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span></li></ul>"},{"id":"t-atypique","kind":"terminal","label":"Syndrome parkinsonien dégénératif atypique","color":"amber","detail":"<h4>Caractéristiques</h4><ul><li>Syndrome parkinsonien associé à d'autres <span class=\"kw-alerte\">drapeaux rouges</span></li><li><span class=\"kw-alerte\">Progression plus rapide</span> que la maladie de Parkinson</li><li><span class=\"kw-alerte\">Réponse faible ou nulle</span> au traitement dopaminergique</li><li><span class=\"kw-alerte\">Survie diminuée</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Atrophie multisystématisée (AMS)</span> : <span class=\"kw-clinique\">syndrome cérébelleux</span> + dysautonomie + irritation pyramidale</li><li><span class=\"kw-etio\">Paralysie supranucléaire progressive (PSP)</span> — maladie de Steele-Richardson</li><li><span class=\"kw-etio\">Démence à corps de Lewy</span></li><li><span class=\"kw-etio\">Dégénérescence cortico-basale</span></li></ul>"}]},"cards":[{"i":"0b491c6feaaa","n":106,"o":"106-1","u":"Diagnostic positif","t":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","q":"Quels sont les principaux prodromes non moteurs pouvant inaugurer une maladie de Parkinson, plusieurs années avant les signes moteurs ?","a":"<p>Les prodromes non moteurs de la maladie de Parkinson incluent :</p><ul><li>Des troubles <strong>digestifs</strong> comme la <strong>constipation</strong>.</li><li>Des troubles de l'<strong>olfaction</strong>, notamment une <strong>hyposmie</strong> ou un déficit de l'odorat.</li><li>Des troubles du <strong>sommeil</strong>, en particulier les <strong>troubles du comportement en sommeil paradoxal (RBD)</strong>, se manifestant par des rêves animés, des cauchemars, et des actes auto- ou hétéro-agressifs.</li><li>La <strong>douleur</strong>, telle qu'une douleur mécanique de l'épaule.</li></ul>"},{"i":"3160430aaae1","n":106,"o":"106-1","u":"Diagnostic positif","t":"Connaître les symptômes qui peuvent inaugurer une maladie de Parkinson","q":"La maladie de Parkinson peut-elle se présenter initialement avec des signes moteurs trompeurs en l'absence de tremblement de repos ? Si oui, lesquels ?","a":"<p>Oui, la maladie de Parkinson peut se révéler par des signes trompeurs mimant d'autres pathologies, avant l'apparition du tremblement de repos caractéristique. Ces manifestations incluent :</p><ul><li>Des symptômes <strong>rhumatologiques</strong> : une <strong>raideur d'un membre</strong> ou une <strong>périarthrite scapulo-humérale</strong> (fréquente dans la maladie de Parkinson).</li><li>Des symptômes <strong>neuropsychiques</strong> : un <strong>ralentissement psychomoteur</strong> pouvant évoquer une dépression.</li></ul>"},{"i":"14a2d15cb702","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelle est la physiopathologie principale du syndrome parkinsonien iatrogène ?","a":"<p>Le syndrome parkinsonien iatrogène est dû au <strong>blocage des récepteurs dopaminergiques</strong> par certains médicaments.</p>"},{"i":"1f52bf306489","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quels sont les médicaments les plus fréquemment mis en cause dans l'induction d'un syndrome parkinsonien iatrogène ?","a":"<ul><li>Les <strong>neuroleptiques</strong> de toutes générations sont les plus fréquents.</li><li>D'autres médicaments comme le <strong>métoclopramide</strong>, la <strong>métopimazine</strong>, la <strong>flunarizine</strong>, l'alimémazine, la méquitazine, la trimétazidine, le lithium, l'<strong>amiodarone</strong> et le <strong>valproate</strong> peuvent également être en cause (neurolptiques dits \"cachés\").</li></ul>"},{"i":"49439c6f6b05","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelle est la première mesure à prendre face à un syndrome parkinsonien iatrogène ?","a":"<p>La première mesure est d'<strong>arrêter le médicament neuroleptique</strong> en cause, si possible.</p>"},{"i":"82125ef887c0","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Quelles sont les caractéristiques cliniques qui orientent vers un syndrome parkinsonien iatrogène par rapport à une maladie de Parkinson typique ?","a":"<ul><li>Le syndrome est plutôt <strong>symétrique</strong> (caractéristique inconstante).</li><li>Le <strong>tremblement</strong> est plus souvent <strong>postural ou d'action</strong> qu'un authentique tremblement de repos.</li><li>Des <strong>dyskinésies bucco-linguo-faciales</strong> peuvent être associées.</li><li>Il y a une <strong>absence de réponse</strong> au traitement dopaminergique.</li></ul>"},{"i":"a6d11a1032eb","n":106,"o":"106-11","u":"Prise en charge","t":"Connaître les médicaments susceptibles d’induire un syndrome parkinsonien","q":"Si l'arrêt du neuroleptique inducteur d'un syndrome parkinsonien iatrogène n'est pas possible, quelles sont les alternatives thérapeutiques ?","a":"<ul><li>Remplacer par un <strong>neuroleptique atypique à faibles effets extrapyramidaux</strong> comme la <strong>clozapine</strong> (nécessitant une surveillance hebdomadaire de la NFS pendant 18 semaines puis mensuelle en raison du risque d'agranulocytose) ou la <strong>quétiapine</strong>.</li><li>Si aucune modification n'est possible, un <strong>correcteur anticholinergique</strong> (ex: tropatépine per os) peut être utilisé, mais jamais en prescription d'emblée en association aux antipsychotiques.</li></ul>"},{"i":"1e1aa035cae6","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quelle particularité de la présentation du syndrome parkinsonien est essentielle pour orienter vers le diagnostic de maladie de Parkinson ?","a":"<p>L'orientation diagnostique vers la maladie de Parkinson est fortement suggérée par une <strong>asymétrie ou unilatéralité persistante</strong> du syndrome parkinsonien. Une présentation strictement symétrique doit faire évoquer d'autres diagnostics, comme une cause iatrogène ou vasculaire.</p>"},{"i":"6bd11f7e3833","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Comment la marche et l'écriture peuvent-elles orienter vers le diagnostic de maladie de Parkinson ?","a":"<p>L'observation de la marche peut révéler des <strong>petits pas</strong> et une <strong>perte du ballant du bras</strong> du côté le plus atteint. Concernant l'écriture, la <strong>micrographie</strong> (réduction progressive de la taille des lettres) est un signe classique.</p>"},{"i":"81a2e0ef35df","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quels signes cliniques spécifiques doivent alerter et faire rechercher d'autres diagnostics que la maladie de Parkinson ?","a":"<p>Certains signes cliniques constituent des <strong>drapeaux rouges</strong>, orientant contre le diagnostic de maladie de Parkinson :</p><ul><li>Un syndrome <strong>strictement symétrique</strong>.</li><li>Des <strong>mouvements oculaires anormaux</strong> (évoquant une paralysie supranucléaire progressive - PSP).</li><li>Une <strong>dysarthrie pseudo-bulbaire précoce</strong> (évoquant PSP, atrophie multisystématisée - AMS).</li><li>Un <strong>tremblement d'action isolé</strong> ou un <strong>tremblement majoré à l'action</strong> (évoquant un tremblement essentiel).</li><li>Une <strong>maladresse cérébelleuse</strong> (dysmétrie au doigt-nez), une <strong>ataxie cérébelleuse</strong>.</li><li>Des <strong>chutes précoces</strong> ou une altération précoce des réflexes posturaux (évoquant PSP, AMS).</li><li>Toute <strong>anomalie neurologique associée</strong> (cérébelleuse, pyramidale, corticale, oculomotrice) en dehors du syndrome parkinsonien lui-même.</li></ul>"},{"i":"b058e3d95544","n":106,"o":"106-12","u":"Contenu multimédia","t":"Chez un patient réel ou sur un cas vidéo, définir les éléments qui orientent vers le diagnostic de maladie de Parkinson","q":"Quels sont les trois éléments clés de la triade clinique qui orientent vers le diagnostic de maladie de Parkinson ?","a":"<p>La triade clinique caractéristique de la maladie de Parkinson comprend :</p><ul><li>Le <strong>tremblement de repos</strong> distal (lèvres, menton, main) à 4-6 Hz.</li><li>La <strong>rigidité plastique en roue dentée</strong>.</li><li>La <strong>bradykinésie</strong> (lenteur et décrément de l'amplitude des mouvements alternatifs rapides, comme l'opposition pouce-index).</li></ul>"},{"i":"1385fa14f4c2","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Comment caractérise-t-on la rigidité plastique retrouvée dans la maladie de Parkinson ?","a":"<p>La rigidité plastique est une résistance constante au mouvement passif, décrite <strong>« en tuyau de plomb »</strong>. Elle se différencie de la rigidité spastique par sa topographie (plus aux extrémités et à la nuque) et sa modalité : lors de la mobilisation passive, elle cède par <strong>à-coups en « roue dentée »</strong>. Elle peut être majorée par la <strong>manœuvre de Froment</strong> (mouvements passifs d'une main associés à une tâche volontaire de l'autre main).</p>"},{"i":"2f35b26d61b7","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Comment définit-on cliniquement le syndrome parkinsonien dans le cadre de la maladie de Parkinson ?","a":"<p>Le syndrome parkinsonien est défini par l'association obligatoire d'une <strong>bradykinésie</strong>, à laquelle s'ajoutent une <strong>rigidité plastique</strong> et/ou un <strong>tremblement de repos</strong>. Une caractéristique cardinale est son <strong>début unilatéral ou asymétrique</strong>, cette asymétrie persistant tout au long de la maladie.</p>"},{"i":"7bdbba41809b","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Quelles sont les caractéristiques cliniques de la bradykinésie dans la maladie de Parkinson ?","a":"<p>La bradykinésie se manifeste par :</p><ul><li>Des <strong>mouvements lents</strong> (ralentissement à l'exécution, décrément de vitesse).</li><li>Une <strong>hypokinésie</strong> (mouvements moins amples) et/ou une <strong>akinésie</strong> (défaut d'initiation).</li><li><strong>Micrographie</strong> (réduction de la taille des lettres à l'écriture).</li><li><strong>Voix monocorde et monotone</strong>.</li><li>Marche lente, à <strong>petits pas</strong>, avec <strong>perte du ballant du bras</strong>.</li><li><strong>Hypomimie faciale</strong>, pauvreté des mouvements spontanés (clignement des yeux).</li><li>Ralentissement des gestes alternatifs rapides (ex: opposition pouce-index, battre à mesure avec le pied).</li></ul>"},{"i":"ec17461cecb9","n":106,"o":"106-2","u":"Diagnostic positif","t":"Décrire les signes cliniques d’une maladie de Parkinson","q":"Quelles sont les principales caractéristiques du tremblement de repos dans la maladie de Parkinson ?","a":"<p>Le tremblement de repos est un tremblement <strong>lent</strong> (<strong>4-6 Hz</strong>), <strong>unilatéral ou asymétrique</strong>, qui <strong>disparaît au mouvement volontaire et pendant le sommeil</strong>. Il touche principalement les <strong>membres en distalité</strong>, les lèvres, le menton et la langue, mais <strong>jamais le chef (la tête)</strong>. Il peut être <strong>aggravé par l'émotion ou le calcul mental</strong>.</p>"},{"i":"049f1f1f70df","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelles associations cliniques à un syndrome parkinsonien évoquent une dégénérescence cortico-basale ou une démence à corps de Lewy plutôt qu'une maladie de Parkinson ?","a":"<p>Des <strong>signes corticaux</strong> (aphasie, apraxie, myoclonies, astéréognosie) orientent vers une dégénérescence cortico-basale. Une <strong>atteinte cognitive précoce</strong> (contemporaine ou précédant le syndrome parkinsonien) suggère une démence à corps de Lewy.</p>"},{"i":"2974788721a3","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelle est la règle générale concernant l'examen neurologique pour le diagnostic de la maladie de Parkinson ?","a":"<p>Pour diagnostiquer la maladie de Parkinson, l'<strong>examen neurologique doit être normal en dehors du syndrome parkinsonien</strong> lui-même.</p>"},{"i":"cd0af5c6b782","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelle association clinique va à l'encontre du diagnostic de maladie de Parkinson et doit faire évoquer une atrophie multisystématisée (AMS) ?","a":"<p>Devant un syndrome parkinsonien, l'association à un <strong>syndrome cérébelleux</strong>, une <strong>atteinte pyramidale</strong> ou une <strong>dysautonomie précoce et sévère</strong> (hypotension orthostatique (HTO) sévère ou incontinence urinaire) doit faire évoquer une atrophie multisystématisée.</p>"},{"i":"e3c781028dbb","n":106,"o":"106-4","u":"Diagnostic positif","t":"Connaître les signes cliniques dont l’association à un syndrome parkinsonien va à l’encontre du diagnostic de maladie de Parkinson","q":"Quelles associations cliniques à un syndrome parkinsonien sont des \"drapeaux rouges\" pour le diagnostic de maladie de Parkinson et orientent vers une paralysie supra-nucléaire progressive (PSP) ?","a":"<p>Les signes qui orientent vers une paralysie supra-nucléaire progressive (maladie de Steele-Richardson) en association avec un syndrome parkinsonien sont des <strong>troubles oculomoteurs</strong>, une <strong>progression rapide avec chutes précoces</strong>, ou des <strong>signes pseudo-bulbaires précoces</strong> (tels que la dysarthrie et la dysphagie).</p>"}]};